-- email_mock seed
BEGIN;
-- English business textsummary；English business textemailretainEnglish business text、UID、English business textitem。
UPDATE messages
SET message_id = REPLACE(message_id, 'msg_ops_', 'msg_archive_'),
    subject = CASE from_addr
      WHEN 'bank@jiangnan.example' THEN 'English business textaccountoperationsEnglish business text · ' || substr(date,1,10) || ' · UID ' || uid
      WHEN 'broker@huazheng.example' THEN 'English business textriskEnglish business textwatch · ' || substr(date,1,10) || ' · UID ' || uid
      WHEN 'law@guomin.example' THEN 'English business textitemEnglish business textmaterialslist · ' || substr(date,1,10) || ' · UID ' || uid
      ELSE 'family officeoperationsEnglish business text · ' || substr(date,1,10) || ' · UID ' || uid
    END,
    body_text = CASE from_addr
      WHEN 'bank@jiangnan.example' THEN 'English business textbankoperationssummary：English business textreconcileEnglish business textaccountEnglish business text、English business text、pendingpayeeEnglish business textcash flow；English business textemailEnglish business text ' || substr(date,1,10) || '，English business text ' || uid || '。'
      WHEN 'broker@huazheng.example' THEN 'English business textbrokerage researchsummary：English business textreconcileEnglish business text、concentration、English business textbuffer、English business textwatch listEnglish business textcash；English business textemailEnglish business text ' || substr(date,1,10) || '，English business text ' || uid || '。'
      WHEN 'law@guomin.example' THEN 'English business textcounselEnglish business textitemsummary：English business textreconcileEnglish business text、English business textdisclosure、English business text、English business text；English business textemailEnglish business text ' || substr(date,1,10) || '，English business textitemEnglish business text ' || uid || '。'
      ELSE 'English business textoperationssummary：English business textreconcileEnglish business text、English business textrent、English business text、taxprepareEnglish business text；English business textemailEnglish business text ' || substr(date,1,10) || '，operationsEnglish business text ' || uid || '。'
    END,
    size = 180 + length(subject)
WHERE message_id LIKE 'msg_ops_%';
COMMIT;
